/** ★戻り先（★見本 `bk('もっと')`）。★ぜんぶ 同じ です。 */
export const BACK_TO = "もっと";

/**
 * ★「もっと」に 並ぶ 7行（★見本 `SC['もっと']`・design-v75）。
 *
 *   ★`key` …… ★どの 束を 開くか（★上の `BUNDLES` と 同じ 字）
 *   ★`name` …… ★行の 字（★束の 題とは ちがいます。★見本の `mLi` の 1つ目）
 *   ★`sub` …… ★下に 添える 小さな 字
 *   ★`needsClass` …… ★教室を 持って いない 方には 出さない 行
 *     ★★見本は `S.noClass` の ときに「学校の機能」を 落とします。
 *     ★★★見本の「見本だけの スイッチ」は 作りません ── ★人の 姿を 切り替える 道具 です。
 *
 *   ★★★下の 2行は **約束** です。★消さないこと ──
 *     ★「ここに 無いものは、下の タブに あります」。
 *     ★★これを 書いたら、★帯の 5つは 5つの まま で なければ なりません。
 */
export const BUNDLE_ENTRANCES = Object.freeze([
  Object.freeze({ key: "しらべる機能", name: "しらべる", sub: "くらべる・かぞえる・受診用の 1枚" }),
  Object.freeze({ key: "つたえる機能", name: "つたえる", sub: "あなたの ページ・紙・お問い合わせ" }),
  Object.freeze({ key: "学校の機能", name: "学校・教室", sub: "名簿・レッスン・門下・行事",
    needsClass: true }),
  Object.freeze({ key: "公演の機能", name: "公演", sub: "香盤表・稽古・当日の 進行" }),
  Object.freeze({ key: "さがす機能", name: "さがす", sub: "伴奏・お仕事を さがす" }),
  Object.freeze({ key: "学ぶ機能", name: "学ぶ", sub: "記事・もっと 深く" }),
  Object.freeze({ key: "アカウントと設定", name: "アカウントと 設定", sub: "プラン・お支払い・退会" })
]);

/** ★「もっと」の 下の 2行（★約束）。 */
export const ENTRANCE_NOTES = Object.freeze([
  "ここに 無いものは、下の タブに あります。",
  "（きょう・記録・ふりかえる・ノート・ひつじ）"
]);

/**
 * ★いま 出す 入口。
 *
 *   ★★★中身が 1行も 無い 束は 出しません ── ★開けたら 空の 1枚に なります。
 *     ★★「押せる のに 空」は、★押せない 札より たちが 悪い（★裁定176 §3 の 考え）。
 *   ★★`hasClass` が 偽の ときは 学校の 行を 落とします（★見本と 同じ）。
 */
export function entrancesOf(o) {
  const opt = o || {};
  const 行ける = typeof opt.canGo === "function" ? opt.canGo : () => true;
  return BUNDLE_ENTRANCES
    .filter((b) => (b.needsClass ? !!opt.hasClass : true))
    .filter((b) => groupsOf(b.key, 行ける).length > 0);
}

/** ★その 束が ある か。★知らない 束は 出しません。 */
export function isBundle(key) {
  return BUNDLES.includes(String(key || ""));
}

/**
 * ★出す 行 だけ。★2つ とも 揃って いる もの です ──
 *
 *   ①★`readyAt` …… ★行き先の 画面が **できた 日**（★この 紙が 持ちます）
 *   ②★`canGo(to)` …… ★呼ぶ 側が **そこへ 行ける** と 答えた もの
 *
 *   ★★★②を 足した わけ（★2026-09-25）──
 *     ★`readyAt` は「画面が ある」と 言うだけ です。
 *     ★★画面が あっても、★**道が つながって いない** ことが あります。
 *       ★★実際、★作った 画面 26枚に 押す 道が ありませんでした。
 *     ★★★`readyAt` だけで 出すと、★押しても 何も 起きない 札に なります。
 *       ★★だから 呼ぶ 側に 聞きます。★道を 1本 つなぐ たびに 1行 増えます。
 *   ★★`canGo` を 渡さない ときは、★これまで どおり `readyAt` だけで 出します。
 *
 *   ★★節が 空に なった ときは、★その 節ごと 出しません（★空の 見出しを 置きません）。
 */
export function groupsOf(key, canGo) {
  const d = BUNDLE_DEF[String(key || "")];
  if (!d) return [];
  const 行ける = typeof canGo === "function" ? canGo : () => true;
  return (d.groups || [])
    .map((g) => ({
      title: g.title || "",
      rows: (g.rows || []).filter((r) => !!r.readyAt && 行ける(r.to))
    }))
    .filter((g) => g.rows.length > 0);
}

/** ★題・1行・断り。 */
export function headOf(key) {
  const d = BUNDLE_DEF[String(key || "")];
  return d ? d.head : "";
}
export function leadOf(key) {
  const d = BUNDLE_DEF[String(key || "")];
  return (d && d.lead) || "";
}
export function notesOf(key) {
  const d = BUNDLE_DEF[String(key || "")];
  return (d && d.notes) || [];
}

/** ★まだ 出して いない 行の 数（★運営の 確かめ 用。★画面に 出しません）。 */
export function notReadyCount(key) {
  const d = BUNDLE_DEF[String(key || "")];
  if (!d) return 0;
  return (d.groups || []).reduce(
    (n, g) => n + (g.rows || []).filter((r) => !r.readyAt).length, 0);
}
